// -----------------------------------------------------------------------------
// tb_fi_ws.v - fault-injection campaign testbench for the weight-stationary
//              designs W1 (labft_top_ws) and W2 (+define+W2: labft_top_ws2,
//              two checkers). Same method as tb/tb_fi.v (V1) and
//              tb/tb_fi_d.v (V1-D), so the outcome tables can be compared.
//
// No hooks in the RTL: faults are applied from here with force / release and
// by depositing values into registers through hierarchical references. The
// case statements that name every site are generated by fi/sites.py
// (variant w1) into fi_sites.vh.
//
// Plusargs:
//   +vec=<dir>     matrices + golden C (scripts/golden.py format, the SAME
//                  files as the OS campaigns: a.hex = columns of A,
//                  b.hex = rows of B, c.hex = C row by row)
//   +faults=<file> one injection per line: "fid site mode cycle mat"
//                  mode 0 = none (golden run), 1 = stuck-at-0, 2 = stuck-at-1,
//                  3 = held-inverted (persistent), 4 = 1-cycle flip at `cycle`
//   +out=<file>    one result line per injection
//
// WS protocol: K cycles loading the rows of B (w_ready), then N cycles
// streaming the rows of A (in_ready); results leave the bottom of column j
// while col_valid[j] = 1. The testbench collects them and compares them with
// the golden C at done.
//
// Result line (same as tb_fi.v):
//   fid site mode cycle mat correct n_wrong alarm hang done_rc mask chk_fault
// -----------------------------------------------------------------------------

`timescale 1ns / 1ps

`define ATOP dut.u_top
`ifdef W2
  `define TWO
`endif
`ifdef W4
  `define TWO
`endif
`ifdef TWO
  `define CHK1 dut.u_chk1
  `define CHK2 dut.u_chk2
  `define TOP  dut
`else
  `define CHK  dut.u_chk
`endif

module tb_fi_ws;

    parameter N          = 4;
    parameter K          = 4;            // must equal N
    parameter DATA_WIDTH = 8;
    parameter ACC_WIDTH  = 32;
    parameter MAXT       = 16;
    localparam TIMEOUT = 2*(1 + K + N + K + N) + 8;

    reg clk = 1'b0;
    always #5 clk = ~clk;

    reg                          rst_n;
    reg                          start;
    reg  [N*DATA_WIDTH-1:0]      w_row;
    reg  [N*DATA_WIDTH-1:0]      a_row;
    wire                         w_ready, in_ready, busy, done, alarm, chk_fault;
    wire [N-1:0]                 col_valid;
    wire [N*ACC_WIDTH-1:0]       c_bot;

`ifdef W4
    labft_top_ws4 #(.N(N), .K(K), .DATA_WIDTH(DATA_WIDTH), .ACC_WIDTH(ACC_WIDTH)) dut (
        .clk(clk), .rst_n(rst_n), .start(start), .w_row(w_row), .a_row(a_row),
        .w_ready(w_ready), .in_ready(in_ready), .busy(busy), .done(done),
        .col_valid(col_valid), .c_bot(c_bot), .alarm(alarm), .chk_fault(chk_fault));
`elsif W2
    labft_top_ws2 #(.N(N), .K(K), .DATA_WIDTH(DATA_WIDTH), .ACC_WIDTH(ACC_WIDTH)) dut (
        .clk(clk), .rst_n(rst_n), .start(start), .w_row(w_row), .a_row(a_row),
        .w_ready(w_ready), .in_ready(in_ready), .busy(busy), .done(done),
        .col_valid(col_valid), .c_bot(c_bot), .alarm(alarm), .chk_fault(chk_fault));
`elsif W3
    labft_top_ws3 #(.N(N), .K(K), .DATA_WIDTH(DATA_WIDTH), .ACC_WIDTH(ACC_WIDTH)) dut (
        .clk(clk), .rst_n(rst_n), .start(start), .w_row(w_row), .a_row(a_row),
        .w_ready(w_ready), .in_ready(in_ready), .busy(busy), .done(done),
        .col_valid(col_valid), .c_bot(c_bot), .alarm(alarm));
    assign chk_fault = 1'b0;
`else
    labft_top_ws #(.N(N), .K(K), .DATA_WIDTH(DATA_WIDTH), .ACC_WIDTH(ACC_WIDTH)) dut (
        .clk(clk), .rst_n(rst_n), .start(start), .w_row(w_row), .a_row(a_row),
        .w_ready(w_ready), .in_ready(in_ready), .busy(busy), .done(done),
        .col_valid(col_valid), .c_bot(c_bot), .alarm(alarm));
    assign chk_fault = 1'b0;
`endif

    `include `FI_SITES

    reg [N*DATA_WIDTH-1:0] amem [0:MAXT*K-1];
    reg [N*DATA_WIDTH-1:0] bmem [0:MAXT*K-1];
    reg [ACC_WIDTH-1:0]    cmem [0:MAXT*N*N-1];

    reg [8*512-1:0] vecdir, faultfile, outfile;
    integer fin, fout, nread, nrun;
    integer fid, site, mode, fcyc, mat;
    integer rc, t, m, ii, jj, nwrong, done_rc, got_done, hang, alarm_s, chkf_s;
    integer got [0:N-1];
    reg     inv_on;
    reg [N*N-1:0]           mask;
    reg [N*N*ACC_WIDTH-1:0] c_seen;      // results collected, C[i][j] at i*N+j

    // held-inverted: re-invert right after every clock edge (as in tb_fi.v)
    always @(posedge clk) begin
        if (inv_on) begin
            #1;
            fi_flip(site);
        end
    end

    // producer: rows of B while w_ready, rows of A while in_ready
    task drive_inputs;
        begin
            w_row = {N*DATA_WIDTH{1'b0}};
            a_row = {N*DATA_WIDTH{1'b0}};
            if (w_ready && t < K) begin
                w_row = bmem[mat*K + t];
                t = t + 1;
            end
            if (in_ready && m < N) begin
                // a.hex holds columns of A; row m of A = element m of each column
                for (jj = 0; jj < K; jj = jj + 1)
                    a_row[jj*DATA_WIDTH +: DATA_WIDTH] = amem[mat*K + jj][m*DATA_WIDTH +: DATA_WIDTH];
                m = m + 1;
            end
        end
    endtask

    // results leaving the array in this cycle
    task collect;
        begin
            for (jj = 0; jj < N; jj = jj + 1)
                if (col_valid[jj]) begin
                    if (got[jj] < N)
                        c_seen[(got[jj]*N + jj)*ACC_WIDTH +: ACC_WIDTH] = c_bot[jj*ACC_WIDTH +: ACC_WIDTH];
                    got[jj] = got[jj] + 1;
                end
        end
    endtask

    task compare_c;
        begin
            nwrong = 0;
            mask = {N*N{1'b0}};
            for (ii = 0; ii < N*N; ii = ii + 1)
                if (c_seen[ii*ACC_WIDTH +: ACC_WIDTH] !== cmem[mat*N*N + ii]) begin
                    nwrong = nwrong + 1;
                    mask[ii] = 1'b1;
                end
            for (jj = 0; jj < N; jj = jj + 1)
                if (got[jj] != N) nwrong = nwrong + 1;   // missing or extra results
        end
    endtask

    task run_one;
        begin
            inv_on = 1'b0;
            rst_n  = 1'b0;
            start  = 1'b0;
            t = 0; m = 0;
            w_row  = {N*DATA_WIDTH{1'b0}};
            a_row  = {N*DATA_WIDTH{1'b0}};
            c_seen = {N*N*ACC_WIDTH{1'b0}};
            for (jj = 0; jj < N; jj = jj + 1) got[jj] = 0;
            @(negedge clk);
            rst_n = 1'b1;
            // persistent fault: installed before the multiply starts
            if (mode == 1) fi_force(site, 1'b0);
            if (mode == 2) fi_force(site, 1'b1);
            if (mode == 3) begin
                fi_flip(site);
                inv_on = 1'b1;
            end
            start = 1'b1;
            @(negedge clk);          // now in rc = 0
            start = 1'b0;
            rc = 0;
            got_done = 0;
            hang = 0;
            done_rc = -1;
            while (!got_done && !hang) begin
                if (mode == 4 && rc == fcyc) fi_flip(site);
                if (mode == 4 && rc == fcyc + 1 && fi_is_net(site)) fi_release(site);
                collect;
                drive_inputs;
                if (done) begin
                    got_done = 1;
                    done_rc = rc;
                    compare_c;
                end else if (rc >= TIMEOUT) begin
                    hang = 1;
                    compare_c;
                    if (nwrong == 0) nwrong = -1;
                end
                if (!got_done && !hang) begin
                    @(negedge clk);
                    rc = rc + 1;
                end
            end
            // alarm latches on the edge that ends the done cycle
            @(negedge clk);
            alarm_s = alarm;
            chkf_s  = chk_fault;
            inv_on = 1'b0;
            if (mode == 1 || mode == 2 || (mode == 4 && fi_is_net(site))) fi_release(site);
            $fdisplay(fout, "%0d %0d %0d %0d %0d %0d %0d %0d %0d %0d %h %0d",
                      fid, site, mode, fcyc, mat, (nwrong == 0 && !hang), nwrong,
                      alarm_s, hang, done_rc, mask, chkf_s);
        end
    endtask

    initial begin
        if (!$value$plusargs("vec=%s", vecdir) || !$value$plusargs("faults=%s", faultfile) ||
            !$value$plusargs("out=%s", outfile)) begin
            $display("FATAL: need +vec= +faults= +out=");
            $finish;
        end
        $readmemh({vecdir, "/a.hex"}, amem);
        $readmemh({vecdir, "/b.hex"}, bmem);
        $readmemh({vecdir, "/c.hex"}, cmem);
        fin  = $fopen(faultfile, "r");
        fout = $fopen(outfile, "w");
        inv_on = 1'b0;
        site = -1;
        nrun = 0;
        nread = $fscanf(fin, "%d %d %d %d %d\n", fid, site, mode, fcyc, mat);
        while (nread == 5) begin
            run_one;
            nrun = nrun + 1;
            nread = $fscanf(fin, "%d %d %d %d %d\n", fid, site, mode, fcyc, mat);
        end
        $fclose(fout);
        $display("FI_DONE runs=%0d", nrun);
        $finish;
    end

endmodule
